for _letter, _values in YANDEX_BOOKING_EXTRAS.items():
    _existing = YANDEX_ACTIVITIES.get(_letter, "").split("|") if YANDEX_ACTIVITIES.get(_letter) else []
    _seen = {" ".join(x.replace("ё", "е").replace("Ё", "Е").split()).casefold() for x in _existing}
    for _value in _values.split("|"):
        _key = " ".join(_value.replace("ё", "е").replace("Ё", "Е").split()).casefold()
        if _key not in _seen:
            _existing.append(_value); _seen.add(_key)
    YANDEX_ACTIVITIES[_letter] = "|".join(_existing)


DEFAULT_CATEGORIES=[x for s in YANDEX_ACTIVITIES.values() for x in s.split('|')]
